+    port.on("message", (message: { ready?: true } & Partial<WorkerResult>) => {
+      if (message.ready) {
+        clearTimeout(startup);
+        ready = true;
+        resolve(handle);
+        return;
+      }
+      takeResult(message as WorkerResult);
+    });
+    worker.on("error", onFailure);
+    worker.on("exit", onFailure);
+  });
