+  return new Promise<SamlParseProbe>((resolve) => {
+    pool.queue.push({
+      id: pool.nextId++,
+      xml: Buffer.from(samlResponseBase64, "base64").toString(),
+      resolve,
+    });
+    pump();
+  });
+};

